// ===================== Fuente de la página: QuickExpress (reparada y con letras del español) =====================
// txt: las minúsculas usan la forma de la mayúscula (más legible) · est: la original, con la estela en las minúsculas
const PES_FONTS = { txt: '', est: '' };
(() => { for (const [fam, k] of [['PES Express', 'txt'], ['PES Express Estela', 'est']]) { try { const s = atob(PES_FONTS[k]), u = new Uint8Array(s.length); for (let i = 0; i < s.length; i++) u[i] = s.charCodeAt(i); const ff = new FontFace(fam, u.buffer); document.fonts.add(ff); ff.load().catch(() => { }); } catch { } } })();

// fuentes libres (licencia SIL OFL) incluidas para que funcionen sin internet:
// Outfit y Big Shoulders para el estilo Moderno · Pixelify Sans y Silkscreen para el Retro
const OFL_FONTS = [
  ['Outfit', '400', ''], ['Outfit', '700', ''],
  ['Big Shoulders', '400', ''], ['Big Shoulders', '700', ''],
  ['Pixelify Sans', '400 700', ''], ['Silkscreen', '400 700', '']
];
(() => { for (const [fam, w, b64] of OFL_FONTS) { try { const s = atob(b64), u = new Uint8Array(s.length); for (let i = 0; i < s.length; i++) u[i] = s.charCodeAt(i); const ff = new FontFace(fam, u.buffer, { weight: w }); document.fonts.add(ff); ff.load().catch(() => { }); } catch { } } })();
